-- Exploration catalogue (Azerfolio/Data/Exploration.lua, generated by tools/gen-exploration.lua).
local wow = require("mocks.wow")

local function load()
    wow.install()
    local ns = {}
    wow.loadAddonFile("Azerfolio/Data/Exploration.lua", "Azerfolio", ns)
    return ns.ExplorationCatalogue
end

return function(t)
    t.test("catalogue has version, build and the 43 tracked zones", function()
        local C = load()
        t.eq(C.dataVersion, 1)
        t.eq(C.clientBuild, 70862)
        t.eq(C.clientVersion, "1.60.1")
        local n = 0
        for _ in pairs(C.zones) do n = n + 1 end
        t.eq(n, 43, "zones") -- docs/research/exploration-validation.md § Zone coverage
    end)

    t.test("every zone has an achievement and unique numeric criteria", function()
        local C = load()
        local seen, total = {}, 0
        for mapID, z in pairs(C.zones) do
            t.eq(type(mapID), "number")
            t.eq(type(z.achievementID), "number", "achievement of " .. mapID)
            t.ok(#z.criteria > 0, "criteria of " .. mapID)
            for _, id in ipairs(z.criteria) do
                t.eq(type(id), "number")
                t.ok(not seen[id], "criteriaID " .. id .. " appears twice")
                seen[id] = true
                total = total + 1
            end
        end
        t.eq(total, 549, "criteria")
    end)

    t.test("Elwynn Forest matches the Phase 1 findings", function()
        local z = load().zones[1429]
        t.eq(z.achievementID, 776)
        t.eq(#z.criteria, 12)
        local has = {}
        for _, id in ipairs(z.criteria) do has[id] = true end
        t.ok(has[1150], "Forest's Edge")
        t.ok(has[1153], "Brackwell Pumpkin Patch")
        t.ok(has[1149], "Stormwind City")
    end)

    t.test("capitals and Zephras Isle have no entry", function()
        local C = load()
        for _, mapID in ipairs({ 1453, 1454, 1455, 1456, 1457, 1458, 2521, 2665 }) do
            t.eq(C.zones[mapID], nil, "map " .. mapID)
        end
    end)
end
